<script setup>
import {computed,onMounted,onBeforeUnmount,ref} from 'vue';import {useRouter} from 'vue-router';import {ElMessage} from 'element-plus';
import {apiClient,currentApiCacheScope} from '../../utils/api.js';import {shanghaiDateTimeText} from '../../utils/shanghai-date.js';
const router=useRouter(),rows=ref([]),search=ref(''),shop=ref(null),category=ref(''),page=ref(1),selection=ref([]),loading=ref(false);let sequence=0;
const shops=computed(()=>[...new Map(rows.value.map(r=>[Number(r.shop_id),{id:Number(r.shop_id),name:r.shop_name}])).values()]);const categories=computed(()=>[...new Set(rows.value.map(r=>r.category_name).filter(Boolean))]);
const filtered=computed(()=>rows.value.filter(row=>(!shop.value||Number(row.shop_id)===shop.value)&&(!category.value||row.category_name===category.value)&&[row.vendor_code,row.payload.card.title,row.shop_name,row.id].some(value=>String(value||'').toLowerCase().includes(search.value.trim().toLowerCase()))));const paged=computed(()=>filtered.value.slice((page.value-1)*20,page.value*20));
const images=row=>row.payload.images||row.payload.variants?.[0]?.images||[];const variants=row=>row.payload.variants||[{video_url:row.payload.video_url}];
function edit(row){if(row.status!=='draft')return router.push({path:'/listing-publish-records',query:{platform:'wb'}});router.push({path:'/listing-automation',query:{platform:'wb',wbDraftId:String(row.id)}});}
async function load(){const id=++sequence,scope=currentApiCacheScope();loading.value=true;try{const r=await apiClient.get('/api/wb/workbench-drafts',{noCache:true});if(id===sequence&&scope===currentApiCacheScope()){rows.value=r.rows||[];page.value=1;selection.value=[];}}catch(e){if(id===sequence&&scope===currentApiCacheScope())ElMessage.error(e.message);}finally{if(id===sequence)loading.value=false;}}
function reset(){rows.value=[];search.value='';shop.value=null;category.value='';load();}
onMounted(()=>{load();window.addEventListener('erp:auth-scope-changed',reset);});onBeforeUnmount(()=>{sequence++;window.removeEventListener('erp:auth-scope-changed',reset);});
</script>
<template><div class="wb-drafts"><div class="draft-tools"><el-select v-model="category" clearable filterable placeholder="全部 WB 类目" @change="page=1"><el-option v-for="c in categories" :key="c" :value="c" :label="c"/></el-select><el-select v-model="shop" clearable placeholder="全部店铺" @change="page=1"><el-option v-for="s in shops" :key="s.id" :value="s.id" :label="s.name"/></el-select><el-input v-model="search" clearable placeholder="草稿 ID / 商品名 / 货号" @input="page=1"/><el-button :loading="loading" @click="load">刷新列表</el-button><el-button :disabled="selection.length!==1||selection[0]?.status!=='draft'" @click="edit(selection[0])">编辑所选</el-button><span>已选 {{selection.length}} / 当前 {{filtered.length}}</span></div><el-table :data="paged" v-loading="loading" border stripe row-key="id" empty-text="暂无 WB 商品草稿" @selection-change="selection=$event"><el-table-column type="selection" width="46"/><el-table-column label="商品" min-width="380"><template #default="{row}"><div class="product-cell"><el-image v-if="images(row).length" :src="images(row)[0]" :preview-src-list="images(row)" preview-teleported fit="cover" class="product-thumb"/><div v-else class="product-thumb empty-thumb">无图</div><div class="product-info"><strong :title="row.payload.card.title">{{row.payload.card.title||'待填写标题'}}</strong><p>{{row.vendor_code}}</p><small>{{images(row).length}} 图 / {{variants(row).filter(v=>v.video_url).length}} 视频 · {{variants(row).length}} 个变体</small></div></div></template></el-table-column><el-table-column prop="category_name" label="WB 类目" min-width="160"/><el-table-column prop="shop_name" label="店铺" min-width="150"/><el-table-column label="上架状态" width="110"><template #default="{row}"><el-tag size="small">{{({draft:'未提交',publishing:'发布处理中',published:'发布完成'})[row.status]||row.status}}</el-tag></template></el-table-column><el-table-column label="价格" width="140"><template #default="{row}">{{row.payload.card.sizes[0]?.price??'待填写'}} CNY</template></el-table-column><el-table-column label="创建时间" width="180"><template #default="{row}">{{shanghaiDateTimeText(row.created_at,{assumeUtcWhenNaive:true})}}</template></el-table-column><el-table-column label="更新（北京）" width="180"><template #default="{row}">{{shanghaiDateTimeText(row.updated_at,{assumeUtcWhenNaive:true})}}</template></el-table-column><el-table-column label="操作" width="110" fixed="right"><template #default="{row}"><el-button type="primary" plain size="small" @click="edit(row)">{{row.status==='draft'?'编辑':'查看发布'}}</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="20" :total="filtered.length" layout="total,prev,pager,next" style="margin-top:12px"/></div></template>
<style scoped>.draft-tools{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:12px;padding:12px;border:1px solid var(--el-border-color-lighter);border-radius:8px}.draft-tools>.el-input{width:300px}.draft-tools>.el-select{width:180px}.draft-tools>span{font-size:12px;color:var(--el-text-color-secondary)}.product-cell{display:flex;align-items:center;gap:10px;min-height:92px}.product-thumb{width:64px;height:84px;flex:none;border-radius:4px}.empty-thumb{display:flex;align-items:center;justify-content:center;background:var(--el-fill-color-light)}.product-info{min-width:0}.product-info strong{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;line-height:1.4}.product-info p{margin:5px 0;color:var(--el-text-color-secondary);font-size:12px}.product-info small{color:var(--el-text-color-secondary)}</style>
